function load(k,d){try{const v=JSON.parse(localStorage.getItem(k));return v??JSON.parse(JSON.stringify(d))}catch{return JSON.parse(JSON.stringify(d))}}
function save(){localStorage.setItem(LS.products,JSON.stringify(products));localStorage.setItem(LS.orders,JSON.stringify(orders));localStorage.setItem(LS.cart,JSON.stringify(cart));localStorage.setItem(LS.events,JSON.stringify(events));localStorage.setItem(LS.settings,JSON.stringify(settings));localStorage.setItem(LS.users,JSON.stringify(users));localStorage.setItem(LS.returns,JSON.stringify(returns));localStorage.setItem(LS.session,JSON.stringify(session));localStorage.setItem(LS.audit,JSON.stringify(audit));localStorage.setItem(LS.creations,JSON.stringify(creations));updateCartCount()}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmt(n){return 'PKR '+Number(n||0).toLocaleString('en-PK')}
function salePrice(p){return Math.round(p.price*(1-(Number(p.discount)||0)/100))}
function formatDate(d){if(!d)return'';return new Date(d+'T00:00:00').toLocaleDateString('en-PK',{day:'numeric',month:'short',year:'numeric'})}
function log(action){audit.unshift({at:new Date().toISOString(),by:currentUser()?.username||'public',action});audit=audit.slice(0,100);save()}
function currentUser(){return session?users.find(u=>u.id===session.userId&&u.active):null}
function can(p){const u=currentUser();return !!u&&(u.role==='Owner'||u.permissions.includes(p))}
function waLink(number,text){return `https://wa.me/${String(number||'').replace(/\D/g,'')}?text=${encodeURIComponent(text)}`}
function updateCartCount(){document.getElementById('cartCount').textContent=cart.length}
function uniqueMsg(){return 'Each catalogue piece is unique. Once payment is confirmed, that original product is permanently Sold & Locked and cannot be sold again.'}
function stars(n){const x=Math.max(0,Math.min(5,Math.round(Number(n)||0)));return '★'.repeat(x)+'☆'.repeat(5-x)}
function mediaFrame(src,alt='SS Collections product'){return `<div class="branded-media"><img src="${src}" alt="${esc(alt)}"><div class="brand-watermark">SS Collections</div><div class="media-social"><span>f SSCollections.SunShah</span><span>◎ ss_collections125</span><span>www.sunshah.net</span><span>WhatsApp 0346 0113599</span></div></div>`}
function socialLinks(){return `<div class="product-social-links"><span>See more:</span><a target="_blank" href="${SOCIAL.facebook}">Facebook</a><a target="_blank" href="${SOCIAL.instagram}">Instagram</a><a target="_blank" href="${SOCIAL.whatsapp}">WhatsApp</a><a target="_blank" href="${SOCIAL.website}">Website</a></div>`}
function productCard(p){const sp=salePrice(p),sold=p.state==='Sold & Locked';return `<article class="product-card ${sold?'sold':''}"><div class="product-image" onclick="location.hash='#product/${p.id}'">${mediaFrame(p.img,p.name)}${sold?'<div class="sold-overlay">SOLD • UNIQUE PIECE</div>':''}</div><div class="product-body"><span class="pill ${p.state.toLowerCase().replace(/\s+/g,'-')}">${esc(p.state)}</span><div class="design-code">${esc(p.code||'')}</div><h3>${esc(p.name)}</h3><div class="rating-line"><span class="stars">${stars(p.rating)}</span> <strong>${Number(p.rating).toFixed(1)}</strong> <small>(${p.reviewCount} reviews)</small></div><div class="price">${p.discount?`<span class="old-price">${fmt(p.price)}</span>${fmt(sp)}<span class="discount-tag">-${p.discount}%</span>`:fmt(p.price)}</div><div class="product-actions"><button onclick="location.hash='#product/${p.id}'">View</button>${p.state==='Available'?`<button class="add" onclick="addToCart(${p.id})">Buy</button>`:`<a href="#custom?ref=${p.id}">Create similar</a>`}</div>${socialLinks()}</div></article>`}

function home(){const featured=products.filter(p=>p.featured&&p.state!=='Archived').slice(0,4),next=events.filter(e=>e.status!=='Completed').sort((a,b)=>a.date.localeCompare(b.date))[0];app.innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">SS Collections by SunShah</span><h1>One piece. One story. One owner.</h1><p>Handmade bags, traditional clothing, accessories and customised creations — each with individual character and never duplicated as the same piece.</p><div class="hero-actions"><a class="primary" href="#shop">Shop unique pieces</a><a class="secondary" href="#custom">Request custom creation</a></div></div><div class="hero-media"><img src="${A.collection}"><div class="hero-card"><strong>Once sold, always unique.</strong><small>${uniqueMsg()}</small></div></div></section><div class="feature-band"><div><strong>One-of-One</strong><span>Catalogue quantity always one</span></div><div><strong>Secure Reservation</strong><span>Reserved when ordered</span></div><div><strong>Dispatch Proof</strong><span>Actual product & parcel photos</span></div><div><strong>Customer Care</strong><span>Returns for wrong / damaged items</span></div></div>${next?`<section class="section"><div class="section-head"><div><span class="eyebrow">Meet SS Collections</span><h2 class="section-title">Visit our next stall</h2></div><a class="ghost" href="#stalls">All stalls & events</a></div><div class="story-grid"><img src="${next.img}"><div class="story-copy"><span class="eyebrow">${esc(next.city)} • ${esc(next.status)}</span><h2>${esc(next.title)}</h2><p><strong>${formatDate(next.date)}</strong><br>${esc(next.time)}<br>${esc(next.venue)}<br>${esc(next.stall)}</p></div></div></section>`:''}<section class="section"><div class="section-head"><div><span class="eyebrow">Selected for you</span><h2 class="section-title">Featured unique pieces</h2></div><a class="ghost" href="#shop">View all</a></div><div class="product-grid">${featured.map(productCard).join('')}</div></section>`}
function shop(cat='All',page=1){const cats=['All','Bags','Travel & Work','Clothing','Accessories','Shoes'];const all=products.filter(p=>p.state!=='Archived'&&(cat==='All'||p.cat===cat));const perPage=8,totalPages=Math.max(1,Math.ceil(all.length/perPage));page=Math.max(1,Math.min(Number(page)||1,totalPages));const list=all.slice((page-1)*perPage,page*perPage);app.innerHTML=`<section class="shop-page"><span class="eyebrow">Unique catalogue</span><h1>Shop SS Collections</h1><div class="filters">${cats.map(c=>`<button class="${c===cat?'active':''}" onclick="shop('${c.replace(/'/g,"\\'")}',1)">${c}</button>`).join('')}</div><div class="product-grid compact-grid">${list.map(productCard).join('')}</div>${totalPages>1?`<div class="pagination">${Array.from({length:totalPages},(_,i)=>`<button class="${i+1===page?'active':''}" onclick="shop('${cat.replace(/'/g,"\\'")}',${i+1})">${i+1}</button>`).join('')}</div>`:''}</section>`}

function productPage(id){const p=products.find(x=>x.id==id);if(!p){shop();return}const imgs=(p.images&&p.images.length?p.images:[p.img]);app.innerHTML=`<section class="product-page"><div class="product-detail"><div class="product-gallery"><div class="detail-image gallery-main" onclick="openLightbox(${p.id},0)">${mediaFrame(imgs[0],p.name)}<div class="zoom-hint">Click image to enlarge</div></div><div class="gallery-thumbs">${imgs.map((src,i)=>`<button onclick="selectProductImage(${p.id},${i})" aria-label="View image ${i+1}">${mediaFrame(src,`${p.name} image ${i+1}`)}</button>`).join('')}</div></div><div class="detail-copy"><span class="pill">${esc(p.state)}</span><span class="eyebrow">${esc(p.cat)}</span><h1>${esc(p.name)}</h1><div class="rating-line large"><span class="stars">${stars(p.rating)}</span> <strong>${Number(p.rating).toFixed(1)}</strong> <small>${p.reviewCount} customer ratings</small></div><div class="price">${p.discount?`<span class="old-price">${fmt(p.price)}</span>${fmt(salePrice(p))}<span class="discount-tag">-${p.discount}%</span>`:fmt(p.price)}</div><p>${esc(p.desc)}</p><div class="unique-note">One unique piece only. ${uniqueMsg()}</div>${p.state==='Available'?`<button class="primary full" onclick="addToCart(${p.id})">Add unique piece to Cart</button>`:`<a class="primary" href="#custom?ref=${p.id}">Request a similar custom creation</a>`}${socialLinks()}</div></div><div class="reviews-section"><div class="section-head"><div><span class="eyebrow">Customer feedback</span><h2>Ratings & reviews</h2></div><div class="service-rating"><span class="stars">★★★★★</span><strong>4.9/5 service rating</strong></div></div><div class="review-grid">${p.reviews.map(r=>`<article class="review-card"><div class="stars">${stars(r.stars)}</div><p>“${esc(r.text)}”</p><small>${esc(r.name)}</small></article>`).join('')}</div><form id="reviewForm" class="review-form"><h3>Share your feedback</h3><div class="two-fields"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Rating</label><select name="stars"><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Fair</option><option value="1">1 - Poor</option></select></div></div><div class="field"><label>Feedback</label><textarea name="text" required></textarea></div><button class="primary">Submit feedback</button></form></div></section>`;document.getElementById('reviewForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));p.reviews.unshift({name:d.name,stars:Number(d.stars),text:d.text});p.reviewCount+=1;p.rating=Math.round(((p.rating*(p.reviewCount-1)+Number(d.stars))/p.reviewCount)*10)/10;save();alert('Thank you. Your feedback is now visible in this prototype.');productPage(p.id)}}
function selectProductImage(id,index){const p=products.find(x=>x.id==id),imgs=p?.images?.length?p.images:[p?.img];if(!p||!imgs[index])return;const main=document.querySelector('.gallery-main');if(main){main.innerHTML=mediaFrame(imgs[index],`${p.name} image ${index+1}`)+'<div class="zoom-hint">Click image to enlarge</div>';main.onclick=()=>openLightbox(id,index)}}
function openLightbox(id,index=0){const p=products.find(x=>x.id==id);if(!p)return;const imgs=p.images?.length?p.images:[p.img];window.__lightbox={id:p.id,index};const box=document.getElementById('lightbox');box.classList.add('open');document.body.classList.add('no-scroll');renderLightbox()}
function renderLightbox(){const st=window.__lightbox;if(!st)return;const p=products.find(x=>x.id==st.id);if(!p)return;const imgs=p.images?.length?p.images:[p.img];st.index=(st.index+imgs.length)%imgs.length;document.getElementById('lightboxMedia').innerHTML=mediaFrame(imgs[st.index],`${p.name} full image ${st.index+1}`);document.getElementById('lightboxCount').textContent=`${st.index+1} / ${imgs.length}`}
function moveLightbox(step){if(window.__lightbox){window.__lightbox.index+=step;renderLightbox()}}
function closeLightbox(){document.getElementById('lightbox').classList.remove('open');document.body.classList.remove('no-scroll');window.__lightbox=null}

function addToCart(id){const p=products.find(x=>x.id===id);if(!p||p.state!=='Available'){alert('This unique piece is no longer available.');return}if(!cart.some(x=>x.id===id))cart.push({id});save();renderCart();openCart()}
function removeCart(id){cart=cart.filter(x=>x.id!==id);save();renderCart()}
function renderCart(){cart=cart.filter(i=>products.find(p=>p.id===i.id)?.state==='Available');localStorage.setItem(LS.cart,JSON.stringify(cart));updateCartCount();const wrap=document.getElementById('cartItems');if(!cart.length){wrap.innerHTML='<div class="empty">Your Cart is empty.</div>';document.getElementById('cartSubtotal').textContent=fmt(0);return}wrap.innerHTML=cart.map(i=>{const p=products.find(x=>x.id===i.id);return `<div class="cart-item"><img src="${p.img}"><div><h4>${esc(p.name)}</h4><small>1 unique piece • ${fmt(salePrice(p))}</small></div><button class="remove" onclick="removeCart(${i.id})">Remove</button></div>`}).join('');document.getElementById('cartSubtotal').textContent=fmt(cart.reduce((s,i)=>s+salePrice(products.find(p=>p.id===i.id)),0))}
function openCart(){document.getElementById('cartDrawer').classList.add('open');document.getElementById('drawerBackdrop').classList.add('open')}function closeCart(){document.getElementById('cartDrawer').classList.remove('open');document.getElementById('drawerBackdrop').classList.remove('open')}
let checkoutPayment='bank';
function checkout(){closeCart();const valid=cart.filter(i=>products.find(p=>p.id===i.id)?.state==='Available');if(!valid.length){cart=[];save();openCart();return}cart=valid;const total=cart.reduce((s,i)=>s+salePrice(products.find(p=>p.id===i.id)),0),tempRef='ORDER NUMBER GENERATED AFTER SUBMISSION';app.innerHTML=`<section class="checkout-page"><h1>Checkout</h1><div class="checkout-grid"><form class="form-card" id="checkoutForm"><h2>Customer details</h2><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Mobile / WhatsApp</label><input name="phone" required placeholder="03xx xxxxxxx"></div><div class="field"><label>Email (optional)</label><input name="email" type="email"></div><div class="field"><label>Delivery address</label><textarea name="address" required></textarea></div><div class="field"><label>City</label><input name="city" required></div><h2 style="margin-top:26px">Choose payment method</h2><div class="payment-tabs">${settings.bankEnabled?'<button type="button" class="payment-option active" data-pay="bank">Online / Bank Transfer</button>':''}${settings.qrEnabled?'<button type="button" class="payment-option" data-pay="qr">QR Payment</button>':''}${settings.cardEnabled?'<button type="button" class="payment-option" data-pay="card">Card Payment</button>':''}</div><div id="paymentPanel"></div><div class="unique-note"><strong>Reconciliation rule:</strong> first place the order to generate your SS Collections order number. Then make payment quoting that exact order number in the payment remarks/reference and submit proof on the next screen.</div><div class="note">Placing the order immediately reserves each unique item for ${Number(settings.reserveHours||24)} hours while payment is verified.</div><button class="primary full" type="submit" style="margin-top:18px">Place order & reserve pieces</button></form><aside class="summary-card"><h2>Order summary</h2>${cart.map(i=>{const p=products.find(x=>x.id===i.id);return `<div class="summary-line"><span>${esc(p.name)}</span><strong>${fmt(salePrice(p))}</strong></div>`}).join('')}<div class="summary-line summary-total"><span>Total</span><strong>${fmt(total)}</strong></div><p class="unique-note">Quantity cannot be increased. Each listing is one unique piece.</p></aside></div></section>`;wirePaymentTabs();document.getElementById('checkoutForm').onsubmit=placeOrder}
function paymentPanel(){const p=document.getElementById('paymentPanel');if(!p)return;if(checkoutPayment==='bank')p.innerHTML=`<div class="payment-panel"><strong>Bank / online transfer</strong><p>Bank: ${esc(settings.bankName)}<br>Account title: ${esc(settings.accountTitle)}<br>Account no: ${esc(settings.accountNumber)}<br>IBAN: ${esc(settings.iban)}</p><small>After your order number is generated, include it in the transfer remarks/reference.</small></div>`;if(checkoutPayment==='qr')p.innerHTML=`<div class="payment-panel"><strong>QR payment</strong><div class="qr-box">${settings.qrImage?`<img src="${settings.qrImage}" alt="Payment QR">`:'<div class="qr-placeholder">Payment QR will be uploaded by Admin</div>'}</div><small>Quote the generated SS Collections order number in payment remarks/reference.</small></div>`;if(checkoutPayment==='card')p.innerHTML=`<div class="payment-panel"><strong>Debit / credit card</strong><p>Card gateway is represented in this prototype. The production Cloudflare version will redirect to a secure payment gateway; Sun Shah will not store card numbers.</p></div>`}
function wirePaymentTabs(){document.querySelectorAll('.payment-option').forEach(b=>b.onclick=()=>{checkoutPayment=b.dataset.pay;document.querySelectorAll('.payment-option').forEach(x=>x.classList.toggle('active',x===b));paymentPanel()});const first=document.querySelector('.payment-option');if(first){checkoutPayment=first.dataset.pay;paymentPanel()}}
async function placeOrder(e){e.preventDefault();const items=cart.filter(i=>products.find(p=>p.id===i.id)?.state==='Available');if(items.length!==cart.length){alert('One item has become unavailable. Please review your cart.');return}const f=new FormData(e.target);try{const r=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({customer_name:f.get('name'),whatsapp:f.get('phone'),email:f.get('email')||'',address:f.get('address')||'',city:f.get('city')||'',payment_method:checkoutPayment,product_ids:items.map(i=>Number(i.id))})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Order could not be placed');const reserveUntil=new Date(j.payment_due_at).getTime(),orderNo=j.order_no,total=Number(j.amount_pkr)||0;items.forEach(i=>{const x=products.find(z=>z.id===i.id);if(x){x.state='Reserved';x.reservedBy=orderNo;x.reserveUntil=reserveUntil}});orders.unshift({orderNo,date:new Date().toISOString(),name:f.get('name'),phone:f.get('phone'),email:f.get('email'),address:f.get('address'),city:f.get('city'),paymentMethod:checkoutPayment,paymentRef:'',receipt:'',status:'Payment Pending',items:items.map(i=>({id:i.id,price:salePrice(products.find(p=>p.id===i.id))})),total,reserveUntil,tracking:'',dispatchPhotos:[],customerDispatchConfirmed:false});cart=[];save();showPostOrder(orderNo)}catch(err){alert('Unable to place order: '+err.message)}}
function showPostOrder(orderNo){const o=orders.find(x=>x.orderNo===orderNo);if(!o)return;const customerMsg=`SS Collections order ${o.orderNo} received. Amount: ${fmt(o.total)}. Payment due: ${new Date(o.reserveUntil).toLocaleString('en-PK')}. Your unique piece(s) are reserved until this due date. If payment is not received by then, the order may be revoked and the product made available to other customers. Please quote ${o.orderNo} in your payment reference.`;const ownerMsg=`New SS Collections order ${o.orderNo} from ${o.name} (${o.phone}). Amount ${fmt(o.total)}. Payment method: ${o.paymentMethod}.`;app.innerHTML=`<section class="checkout-page"><div class="success-box"><h2>Order received & reserved</h2><p>Your order number is</p><div class="order-ref"><strong>${o.orderNo}</strong></div><p><strong>Use this exact order number in your payment reference / remarks.</strong></p></div><div class="checkout-grid"><form class="form-card" id="payProofForm"><h2>Complete payment</h2>${o.paymentMethod==='bank'?`<div class="payment-panel"><strong>Bank / online transfer</strong><p>Bank: ${esc(settings.bankName)}<br>Account title: ${esc(settings.accountTitle)}<br>Account no: ${esc(settings.accountNumber)}<br>IBAN: ${esc(settings.iban)}</p></div>`:o.paymentMethod==='qr'?`<div class="payment-panel"><strong>QR payment</strong><div class="qr-box">${settings.qrImage?`<img src="${settings.qrImage}">`:'<div class="qr-placeholder">Payment QR will be uploaded by Admin</div>'}</div></div>`:'<div class="payment-panel"><strong>Card payment</strong><p>Prototype only. Production will open a secure card gateway.</p></div>'}<div class="unique-note">Payment remarks / reference must contain: <strong>${o.orderNo}</strong></div><div class="field"><label>Transaction / payment reference</label><input name="paymentRef" required placeholder="e.g. ${o.orderNo} / bank transaction ID"></div><div class="field"><label>Payment receipt / screenshot</label><input name="receipt" type="file" accept="image/*,.pdf"></div><button class="primary full">Submit payment for verification</button></form><div class="form-card"><h2>WhatsApp confirmations</h2><div class="wa-preview">${esc(customerMsg)}</div><a class="primary" href="${waLink(o.phone,customerMsg)}" target="_blank">Customer confirmation</a><div class="wa-preview">${esc(ownerMsg)}</div><a class="secondary" href="${waLink(OWNER_WA,ownerMsg)}" target="_blank">Notify owner</a></div></div></section>`;document.getElementById('payProofForm').onsubmit=e=>submitPaymentProof(e,o.orderNo)}
async function submitPaymentProof(e,no){e.preventDefault();const o=orders.find(x=>x.orderNo===no),f=new FormData(e.target),ref=String(f.get('paymentRef')||'');if(!ref.toUpperCase().includes(no.toUpperCase())){alert('Please include the full SS Collections order number '+no+' in the payment reference.');return}o.paymentRef=ref;const file=f.get('receipt');if(file&&file.size&&file.type.startsWith('image/')&&file.size<700000)o.receipt=await readFile(file);log(`Payment proof submitted for ${no}`);save();const c=`SS Collections ${no}: payment proof received and awaiting verification. We will confirm on WhatsApp after verification.`;const own=`Payment proof submitted for SS Collections order ${no}. Please verify payment in Admin.`;app.innerHTML=`<section class="section"><div class="success-box"><h2>Payment submitted for verification</h2><p>${esc(c)}</p><div class="button-row"><a class="primary" target="_blank" href="${waLink(o.phone,c)}">Customer WhatsApp</a><a class="secondary" target="_blank" href="${waLink(OWNER_WA,own)}">Notify owner</a><a class="secondary" href="#track">Track order</a></div></div></section>`}
function track(){app.innerHTML=`<section class="track-page"><h1>Track your order</h1><div class="track-card"><p>Enter your SS Collections order number.</p><form id="trackForm"><div class="field"><label>Order number</label><input id="trackNo" placeholder="SS-2026-123456" required></div><button class="primary">Track order</button></form><div id="trackResult"></div></div></section>`;document.getElementById('trackForm').onsubmit=e=>{e.preventDefault();showTrack(document.getElementById('trackNo').value.trim().toUpperCase())}}
function showTrack(q){const o=orders.find(x=>x.orderNo.toUpperCase()===q),r=document.getElementById('trackResult');if(!o){r.innerHTML='<div class="note" style="margin-top:20px">No order found in this browser prototype.</div>';return}const stages=['Payment Pending','Payment Confirmed','Preparing','Awaiting Customer Dispatch Confirmation','Dispatched','Delivered'],idx=stages.indexOf(o.status);r.innerHTML=`<div class="success-box"><strong>${o.orderNo}</strong><br>${esc(o.name)} • ${fmt(o.total)}<br><span class="small-muted">Payment reference must include ${o.orderNo}</span></div>${stages.map((s,i)=>`<div class="status-line ${i<=idx?'done':''}"><span class="status-dot"></span><div><strong>${s}</strong><small>${i===idx?'Current status':''}</small></div></div>`).join('')}${o.status==='Cancelled'?'<div class="note">This order was cancelled.</div>':''}${o.tracking?`<div class="bank-box"><strong>Courier / tracking</strong><br>${esc(o.tracking)}</div>`:''}${o.dispatchPhotos?.length?`<div class="dispatch-box"><h3>Actual product & parcel being dispatched</h3><p>Please review these photos and confirm that the correct product/parcel is being sent.</p><div class="proof-grid">${o.dispatchPhotos.map(x=>`<img src="${x}">`).join('')}</div>${!o.customerDispatchConfirmed?`<button class="primary" style="margin-top:12px" onclick="confirmDispatch('${o.orderNo}')">I confirm this is my order</button>`:'<div class="success-box">Customer confirmed the dispatch photos.</div>'}</div>`:''}${o.status==='Delivered'?`<div class="button-row"><a class="secondary" href="#return-request?order=${o.orderNo}">Report wrong / damaged product</a></div>`:''}`}
function confirmDispatch(no){const o=orders.find(x=>x.orderNo===no);if(!o)return;o.customerDispatchConfirmed=true;if(o.status==='Awaiting Customer Dispatch Confirmation')o.status='Preparing';log(`Customer confirmed dispatch photos for ${no}`);save();showTrack(no);alert('Thank you. Your confirmation has been recorded.')}
function stalls(){const sorted=[...events].sort((a,b)=>a.date.localeCompare(b.date));app.innerHTML=`<section class="events-page"><span class="eyebrow">Meet the makers</span><h1>Stalls & events</h1><p style="max-width:760px;color:var(--muted);line-height:1.8">Visit Sun Shah at exhibitions, pop-ups and stalls in different cities. <strong>We are offering discounts to customers at our events and special discounts for people who click “Yes”.</strong></p><div class="event-grid" style="margin-top:28px">${sorted.map(e=>`<article class="event-card"><img src="${e.img||A.collection}"><div class="event-body"><span class="event-status">${esc(e.status)}</span><h3>${esc(e.title)}</h3><div class="event-meta"><strong>${esc(e.city)}</strong><br>${formatDate(e.date)} • ${esc(e.time)}<br>${esc(e.venue)}<br>${esc(e.stall)}</div><p>${esc(e.details)}</p><div class="interest-box"><strong>Interested in visiting?</strong><div><button onclick="eventInterest(${e.id},'yes',this)">Yes</button><button onclick="eventInterest(${e.id},'no',this)">No</button><button onclick="eventInterest(${e.id},'not_available',this)">Not available</button></div><small>One click is enough — no form required.</small></div>${e.map?`<a class="secondary" href="${esc(e.map)}" target="_blank">Open location</a>`:''}</div></article>`).join('')||'<div class="empty">No stalls announced.</div>'}</div></section>`}
async function eventInterest(id,choice,btn){try{const key=localStorage.getItem('ssVisitorKey')||crypto.randomUUID();localStorage.setItem('ssVisitorKey',key);const r=await fetch(`/api/events/${id}/interest`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({choice,visitor_key:key})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Could not save');const box=btn.closest('.interest-box');box.innerHTML=choice==='yes'?'<strong>Thank you ❤️</strong><p>You are marked as interested. Special discounts are available for customers who selected Yes.</p>':'<strong>Thank you for letting us know.</strong>'}catch(e){alert(e.message)}}
const CREATION_CATS=['All','Bags','Dresses','Jewellery','Hair Accessories','Travel Bags','Winter Collection','Summer Collection','Wedding','Home Décor','Shoes','Other'];
function creationCard(c){return `<article class="creation-card"><div onclick="openLightbox(['${c.img}'],0,'${esc(c.title)}')">${mediaFrame(c.img,c.title)}</div><div class="creation-body"><div class="design-code">${esc(c.id)}</div><span class="creation-status">${esc(c.status)}</span><h3>${esc(c.title)}</h3><small>${esc(c.season||'')} • ${esc(c.note||'')}</small><div class="creation-actions"><a class="primary" href="#custom?code=${encodeURIComponent(c.id)}">Request similar</a><a class="secondary" target="_blank" href="${waLink(OWNER_WA,`I am interested in design ${c.id} - ${c.title}`)}">WhatsApp</a></div></div></article>`}
function creationsPage(cat='All'){const list=creations.filter(c=>cat==='All'||c.cat===cat||c.season===cat);app.innerHTML=`<section class="shop-page"><span class="eyebrow">15 years of ideas, craft & custom work</span><h1>Our Creations</h1><div class="capability-banner"><h2>See what SS Collections can create for you</h2><p>Browse past, current, seasonal and future designs. Every design has a reference code. Sold pieces remain here for inspiration — request a similar customised piece using its code.</p></div><div class="gallery-toolbar">${CREATION_CATS.map(c=>`<button class="${c===cat?'active':''}" onclick="creationsPage('${c.replace(/'/g,"\\'")}')">${c}</button>`).join('')}</div><div class="creation-grid">${list.map(creationCard).join('')||'<div class="empty">No designs in this category yet.</div>'}</div></section>`}
function creationAdmin(){return `<div class="admin-card"><div class="section-head"><div><h2>Our Creations gallery</h2><p>Upload past, current, seasonal or future work. Each design gets a permanent reference code.</p></div></div><form id="creationForm"><div class="gallery-upload-grid"><div class="field"><label>Design code</label><input name="code" placeholder="e.g. SHO-00001" required></div><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Category</label><select name="cat">${CREATION_CATS.filter(x=>x!=='All').map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status"><option>Available Now</option><option>Sold</option><option>Past Collection</option><option>Seasonal</option><option>Coming Soon</option><option>Inspiration Only</option></select></div><div class="field"><label>Season / collection</label><select name="season"><option>All Season</option><option>Winter Collection</option><option>Summer Collection</option><option>Wedding</option><option>Travel</option></select></div><div class="field"><label>Picture</label><input id="creationPic" type="file" accept="image/*" required></div></div><div class="field"><label>Note</label><input name="note" placeholder="e.g. Similar custom design possible"></div><div class="save-bar"><button class="primary">Save / Proceed</button></div></form><div style="margin-top:20px">${creations.map(c=>`<div class="creation-admin-row"><img src="${c.img}"><div><strong>${esc(c.id)} • ${esc(c.title)}</strong><br><small>${esc(c.cat)} • ${esc(c.status)}</small></div><span>${esc(c.season||'')}</span><button class="mini danger" onclick="deleteCreation('${c.id}')">Delete</button></div>`).join('')}</div></div>`}
function deleteCreation(id){if(!confirm(`Delete gallery design ${id}?`))return;creations=creations.filter(c=>c.id!==id);log(`Creation deleted: ${id}`);save();admin('creations')}
function custom(){const m=(location.hash||'').match(/ref=(\d+)/),cm=(location.hash||'').match(/code=([^&]+)/),p=m?products.find(x=>x.id==m[1]):null,c=cm?creations.find(x=>x.id===decodeURIComponent(cm[1])):null;app.innerHTML=`<section class="custom-page"><h1>Custom order</h1><div class="custom-grid"><div class="custom-preview">${p||c?mediaFrame((p||c).img,(p||c).name||(p||c).title):''}</div><form class="form-card" id="customForm"><h2>${p?'Inspired by: '+esc(p.name):c?'Reference design: '+esc(c.id)+' • '+esc(c.title):'Tell us what you want'}</h2>${p||c?'<div class="unique-note">The reference design will not be copied identically. A new unique piece can be inspired by its style, colour, craft or technique.</div>':''}<div class="field"><label>Name</label><input required></div><div class="field"><label>WhatsApp number</label><input required></div><div class="field"><label>Product type</label><select><option>Bag</option><option>Travel / office bag</option><option>Dress / clothing</option><option>Jewellery</option><option>Hair accessory</option><option>Shoes</option><option>Home décor</option><option>Other</option></select></div><div class="field"><label>Colour / size / measurements</label><input></div><div class="field"><label>Reference image</label><input type="file" accept="image/*"></div><div class="field"><label>Instructions</label><textarea></textarea></div><button class="primary full">Submit custom request</button></form></div></section>`;document.getElementById('customForm').onsubmit=async e=>{e.preventDefault();const inputs=e.target.querySelectorAll('input,select,textarea'),fd=new FormData();fd.set('customer_name',inputs[0].value);fd.set('whatsapp',inputs[1].value);fd.set('product_type',inputs[2].value);fd.set('colour_size',inputs[3].value);if(inputs[4]?.files?.[0])fd.set('media',inputs[4].files[0]);fd.set('instructions',inputs[5]?.value||'');fd.set('reference_code',c?.id||p?.code||'');try{const r=await fetch('/api/custom-requests',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw new Error(j.error||'Could not submit');alert('Thank you. Your custom request has been received by SS Collections.');location.hash='#home'}catch(err){alert(err.message)}}}
function story(){app.innerHTML=`<section class="section"><div class="story-grid"><img src="${A.bags}"><div class="story-copy"><span class="eyebrow">Our story</span><h2>Handmade, personal and deliberately unique.</h2><p>Sun Shah by SS Collections brings distinctive traditional products, customised orders and direct customer relationships into one digital home.</p><p>A sold item remains part of the visual archive but is locked from resale. Similar customised work may be requested, but the original one-off product is never duplicated as the same item.</p></div></div></section>`}
function returnsPolicy(){app.innerHTML=`<section class="section"><span class="eyebrow">Customer care</span><h1>Returns & refunds</h1><div class="policy-grid"><div class="policy-card"><h3>Eligible returns</h3><p>Returns may be requested when a wrong product is sent, a product has a confirmed workmanship defect, or the parcel/product is damaged in transit.</p><p><strong>Transit damage is Sun Shah's responsibility to the customer.</strong></p></div><div class="policy-card"><h3>Handmade variation</h3><p>Small natural variations in handmade work are part of the product's individual character and are not automatically treated as defects.</p></div><div class="policy-card"><h3>Evidence & verification</h3><p>Customers should provide clear photographs of the outer parcel, packaging and affected product. Refund is processed after Sun Shah receives the returned product and confirms the defect / wrong item / transit damage.</p></div><div class="policy-card"><h3>Refund time</h3><p>${esc(settings.returnDaysText)}</p></div></div><div class="return-steps"><div><strong>1.</strong> Submit return request with order number, reason and photos.</div><div><strong>2.</strong> Admin reviews and, if accepted, provides return instructions.</div><div><strong>3.</strong> Sun Shah receives and inspects the returned item.</div><div><strong>4.</strong> Confirmed eligible refund is processed within 15 working days.</div></div><div class="button-row" style="margin-top:24px"><a class="primary" href="#return-request">Request a return</a></div></section>`}
function returnRequest(){const m=(location.hash||'').match(/order=([^&]+)/),preset=m?decodeURIComponent(m[1]):'';app.innerHTML=`<section class="section"><span class="eyebrow">Returns</span><h1>Request a return</h1><form class="form-card" id="returnForm" style="max-width:760px"><div class="field"><label>Order number</label><input name="orderNo" value="${esc(preset)}" required></div><div class="field"><label>WhatsApp number used on order</label><input name="phone" required></div><div class="field"><label>Reason</label><select name="reason"><option>Wrong product received</option><option>Product damaged in transit</option><option>Workmanship defect</option><option>Other</option></select></div><div class="field"><label>Describe the issue</label><textarea name="details" required></textarea></div><div class="field"><label>Evidence photos (parcel / packaging / product)</label><input id="returnPics" type="file" accept="image/*" multiple></div><div class="note">For transit damage, please include photos of the outer parcel and packaging as well as the damaged product.</div><button class="primary">Submit return request</button></form></section>`;document.getElementById('returnForm').onsubmit=saveReturn}
async function saveReturn(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),o=orders.find(x=>x.orderNo.toUpperCase()===d.orderNo.trim().toUpperCase());if(!o||String(o.phone).replace(/\D/g,'').slice(-10)!==String(d.phone).replace(/\D/g,'').slice(-10)){alert('Order number and WhatsApp number do not match this prototype record.');return}const files=[...document.getElementById('returnPics').files].slice(0,3),pics=[];for(const f of files){if(f.size<700000)pics.push(await readFile(f))}const id='RET-'+String(Date.now()).slice(-6);returns.unshift({id,orderNo:o.orderNo,phone:d.phone,reason:d.reason,details:d.details,pics,status:'Requested',created:new Date().toISOString(),receivedDate:'',verifiedDate:'',refundDate:''});log(`Return ${id} requested for ${o.orderNo}`);save();const msg=`SS Collections return request ${id} received for order ${o.orderNo}. Status: Requested. We will review the submitted details and contact you on WhatsApp.`;app.innerHTML=`<section class="section"><div class="success-box"><h2>Return request received</h2><p>Return reference: <strong>${id}</strong></p><p>${esc(msg)}</p><a class="primary" href="${waLink(o.phone,msg)}" target="_blank">Open WhatsApp confirmation</a></div></section>`}
function staffLogin(){if(currentUser()){location.hash='#admin';return}app.innerHTML=`<section class="login-wrap"><div class="login-card"><span class="eyebrow">Authorised staff only</span><h1>Staff login</h1><p>Public visitors cannot view SS Collections administration data.</p><form id="loginForm"><div class="field"><label>Login ID</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="primary full">Sign in</button></form><div class="note" style="margin-top:18px"><strong>Prototype owner login:</strong><br>Login ID: owner<br>Password: SunShah@V3</div></div></section>`;document.getElementById('loginForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),u=users.find(x=>x.username===d.username&&x.password===d.password&&x.active);if(!u){alert('Invalid or disabled login.');return}session={userId:u.id,loginAt:new Date().toISOString()};log(`Staff login: ${u.username}`);save();location.hash='#admin'}}
function logout(){session=null;save();location.hash='#home'}
const labels={dashboard:'Dashboard',products:'Products',orders:'Orders',returns:'Returns & Refunds',events:'Stalls & Events',creations:'Our Creations',users:'Users & Agents',settings:'Settings'};
function admin(tab='dashboard'){const u=currentUser();if(!u){location.hash='#staff-login';return}if(!can(tab)&&tab!=='dashboard')tab='dashboard';const tabs=['dashboard','products','orders','returns','events','creations','users','settings'];app.innerHTML=`<section class="admin-page"><div class="admin-topbar"><div><span class="eyebrow">Secure owner / agent area</span><h1>Admin</h1></div><div class="admin-user"><div><strong>${esc(u.name)}</strong><br><span class="role-badge">${esc(u.role)}</span></div><button class="mini" onclick="logout()">Log out</button></div></div><div class="admin-shell"><aside class="admin-menu"><h3>Manage</h3>${tabs.map(t=>`<button class="${tab===t?'active':''} ${can(t)?'':'locked'}" onclick="admin('${t}')">${labels[t]}</button>`).join('')}</aside><div class="admin-content">${adminTab(tab)}</div></div></section>`;wireAdmin(tab)}
function adminTab(tab){const counts={available:products.filter(p=>p.state==='Available').length,reserved:products.filter(p=>p.state==='Reserved').length,sold:products.filter(p=>p.state==='Sold & Locked').length,returns:returns.filter(r=>!['Refunded','Rejected'].includes(r.status)).length};const stats=`<div class="admin-stats"><div class="stat"><strong>${counts.available}</strong><span>Available</span></div><div class="stat"><strong>${counts.reserved}</strong><span>Reserved</span></div><div class="stat"><strong>${counts.sold}</strong><span>Sold & locked</span></div><div class="stat"><strong>${counts.returns}</strong><span>Open returns</span></div></div>`;if(tab==='dashboard')return stats+`<div class="admin-card"><h2>Business controls</h2><div class="unique-note">Manage products, unique-piece status, Our Creations, orders, events and customer service from one operational area.</div></div><div class="admin-card" style="margin-top:18px"><h2>Recent audit trail</h2><div class="audit-list">${audit.slice(0,10).map(a=>`<div>${new Date(a.at).toLocaleString()} • <strong>${esc(a.by)}</strong> • ${esc(a.action)}</div>`).join('')||'No activity yet.'}</div></div>`;if(tab==='products')return stats+productAdmin();if(tab==='orders')return stats+orderAdmin();if(tab==='returns')return stats+returnAdmin();if(tab==='events')return eventAdmin();if(tab==='creations')return creationAdmin();if(tab==='users')return userAdmin();if(tab==='settings')return settingsAdmin();return stats}
function productAdmin(){return `<div class="admin-card"><div class="section-head"><h2>Products</h2><button class="primary" onclick="showProductForm()">Add unique product</button></div><div class="save-rule">No product change is applied until <strong>Save changes</strong> is clicked.</div><div id="productEditor"></div><div class="admin-table">${products.map(p=>`<div class="admin-row" style="grid-template-columns:64px 1.5fr .8fr .8fr 1fr">${mediaFrame(p.img,p.name)}<div><strong>${esc(p.name)}</strong><br><small>${esc(p.cat)} • ${esc(p.state)}</small></div><div>${fmt(p.price)}${p.discount?`<br><small>-${p.discount}%</small>`:''}</div><div>${p.discount||0}% discount</div><div><button class="mini" onclick="showProductForm(${p.id})">Edit / Save</button></div></div>`).join('')}</div></div>`}
function showProductForm(id){const p=id?products.find(x=>x.id===id):null,box=document.getElementById('productEditor');const existing=p?.images?.length?p.images:[p?.img].filter(Boolean);box.innerHTML=`<form id="productForm" class="admin-card" style="margin:14px 0;background:#fbf6f0"><h3>${p?'Edit product':'Add unique product'}</h3><div class="two-fields"><div class="field"><label>Name</label><input name="name" required value="${esc(p?.name||'')}"></div><div class="field"><label>Category</label><select name="cat">${['Bags','Travel & Work','Clothing','Accessories','Shoes'].map(c=>`<option ${p?.cat===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="two-fields"><div class="field"><label>Price</label><input name="price" type="number" required value="${p?.price||''}"></div><div class="field"><label>Discount %</label><input name="discount" type="number" min="0" max="90" value="${p?.discount||0}"></div></div><div class="field"><label>Description</label><textarea name="desc">${esc(p?.desc||'')}</textarea></div><div class="field"><label>Product pictures (up to 8)</label><input id="prodPics" type="file" accept="image/*" multiple><small>First image is the catalogue cover. Multiple angles help customers review the unique item before purchase.</small></div>${existing.length?`<div class="admin-gallery-preview">${existing.map((x,i)=>`<div>${mediaFrame(x,`${p?.name||'Product'} image ${i+1}`)}<small>${i===0?'Cover image':`Image ${i+1}`}</small></div>`).join('')}</div>`:''}<label class="checkbox-row"><input name="featured" type="checkbox" ${p?.featured?'checked':''}> Featured on homepage</label><div class="save-bar"><button type="button" class="secondary" onclick="document.getElementById('productEditor').innerHTML=''">Cancel</button><button class="primary">Save changes</button></div></form>`;let images=[...existing];document.getElementById('prodPics').onchange=async e=>{const fs=[...e.target.files].slice(0,8);const added=[];for(const f of fs){if(f.size<900000)added.push(await readFile(f));else alert(`${f.name}: use image under 900 KB in this local prototype. Production R2 will support larger images.`)}if(added.length)images=added};document.getElementById('productForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!images.length){alert('Please add at least one product picture.');return}if(!confirm('Save these product changes?'))return;if(p){Object.assign(p,{name:d.name,cat:d.cat,price:Number(d.price),discount:Number(d.discount)||0,desc:d.desc,images,img:images[0],featured:e.target.featured.checked});log(`Product updated: ${p.name}`)}else{products.unshift({id:Date.now(),name:d.name,cat:d.cat,price:Number(d.price),discount:Number(d.discount)||0,state:'Available',images,img:images[0],desc:d.desc,featured:e.target.featured.checked,rating:5,reviewCount:0,reviews:[]});log(`Product added: ${d.name}`)}save();admin('products')}}

function orderAdmin(){return `<div class="admin-card"><h2>Orders</h2><div class="save-rule">Status, tracking and dispatch-photo changes are applied only after <strong>Save / Proceed</strong>.</div>${orders.length?orders.map(o=>`<form class="proof-card order-edit-form" data-order="${o.orderNo}" style="margin:14px 0"><div class="section-head"><div><strong>${o.orderNo}</strong><br><small>${esc(o.name)} • ${esc(o.phone)} • ${fmt(o.total)}</small></div><span class="pill">${esc(o.status)}</span></div><p><strong>Payment:</strong> ${esc(o.paymentMethod||'bank')} • Ref: ${esc(o.paymentRef||'Not entered')}</p><div class="two-fields"><div class="field"><label>Status</label><select name="status">${['Payment Pending','Payment Confirmed','Preparing','Awaiting Customer Dispatch Confirmation','Dispatched','Delivered','Cancelled'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Courier / tracking</label><input name="tracking" value="${esc(o.tracking||'')}"></div></div><div class="field"><label>Add actual product & packed parcel photos</label><input name="dispatchPics" type="file" accept="image/*" multiple></div>${o.dispatchPhotos?.length?`<div class="image-stack">${o.dispatchPhotos.map(x=>mediaFrame(x,`Parcel ${o.orderNo}`)).join('')}</div><p><strong>Customer confirmation:</strong> ${o.customerDispatchConfirmed?'Confirmed':'Pending'}</p><div class="button-row"><a class="secondary" target="_blank" href="${waLink(o.phone,dispatchMsg(o))}">Send photos notice on WhatsApp</a></div>`:''}${o.status==='Payment Confirmed'?`<div class="button-row"><a class="secondary" target="_blank" href="${waLink(o.phone,`Your payment for order no. ${o.orderNo} has been received by SS Collections. Your order will be dispatched in 3 working days and a confirmation message along with tracking ID will be shared with you via WhatsApp.\n\nRegards,\nSS Collections`)}">Send payment confirmation on WhatsApp</a></div>`:''}<div class="save-bar"><button class="primary">Save / Proceed</button></div></form>`).join(''):'<div class="empty">No orders yet.</div>'}</div>`}
function dispatchMsg(o){return `SS Collections order ${o.orderNo}: actual product and packed parcel photos are ready for your confirmation before dispatch. Please open Track Order and confirm the parcel. Transit damage remains Sun Shah's responsibility.`}
async function saveOrderEdit(form){const no=form.dataset.order,o=orders.find(x=>x.orderNo===no);if(!o)return;const status=form.status.value,tracking=form.tracking.value.trim(),old=o.status;if(!confirm(`Save / proceed with changes to ${no}?`))return;if(status==='Payment Confirmed'&&old==='Payment Pending'){o.items.forEach(it=>{const p=products.find(x=>x.id===it.id);if(p&&p.state==='Reserved'&&p.reservedBy===no){p.state='Sold & Locked';p.soldOrder=no;p.soldAt=Date.now()}});log(`Payment confirmed for ${no}; products permanently locked`)}if(status==='Cancelled'&&old==='Payment Pending'){o.items.forEach(it=>{const p=products.find(x=>x.id===it.id);if(p&&p.state==='Reserved'&&p.reservedBy===no){p.state='Available';delete p.reservedBy}});log(`Pending order ${no} cancelled; reservation released`)}if(old==='Payment Confirmed'&&status==='Cancelled')alert('Products remain Sold & Locked because payment had already been confirmed.');o.status=status;o.tracking=tracking;const files=form.dispatchPics.files;for(const f of [...files].slice(0,4)){if(f.size<700000)o.dispatchPhotos.push(await readFile(f))}if(files.length&&o.dispatchPhotos.length&&status==='Preparing')o.status='Awaiting Customer Dispatch Confirmation';log(`Order ${no} changes saved`);save();admin('orders')}

function returnAdmin(){return `<div class="admin-card"><h2>Returns & refunds</h2><div class="save-rule">Return changes require <strong>Save / Proceed</strong>.</div>${returns.map(r=>`<form class="return-card return-edit-form" data-return="${r.id}" style="margin:14px 0"><div class="section-head"><div><strong>${r.id}</strong> • ${r.orderNo}<br><small>${esc(r.reason)}</small></div><span class="pill">${esc(r.status)}</span></div><p>${esc(r.details)}</p>${r.pics?.length?`<div class="proof-grid">${r.pics.map(x=>mediaFrame(x,`Return ${r.id}`)).join('')}</div>`:''}<div class="two-fields"><div class="field"><label>Status</label><select name="status">${['Requested','Under Review','Approved for Return','Returned to Owner','Defect Confirmed','Refund Processing','Refunded','Rejected'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Owner received date</label><input name="receivedDate" type="date" value="${r.receivedDate||''}"></div></div><div class="small-muted">${esc(settings.returnDaysText)}</div><div class="save-bar"><button class="primary">Save / Proceed</button></div></form>`).join('')||'<div class="empty">No return requests.</div>'}</div>`}
function saveReturnEdit(form){const id=form.dataset.return,r=returns.find(x=>String(x.id)===String(id));if(!r)return;if(!confirm(`Save / proceed with return ${id}?`))return;const status=form.status.value;r.status=status;r.receivedDate=form.receivedDate.value;if(status==='Defect Confirmed'&&!r.verifiedDate)r.verifiedDate=new Date().toISOString().slice(0,10);if(status==='Refunded'&&!r.refundDate)r.refundDate=new Date().toISOString().slice(0,10);log(`Return ${id} changes saved: ${status}`);save();admin('returns')}

function eventAdmin(){return `<div class="admin-card"><h2>Stalls & events</h2><form id="eventForm"><div class="two-fields"><div class="field"><label>City</label><input name="city" required></div><div class="field"><label>Date</label><input type="date" name="date" required></div></div><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Venue</label><input name="venue" required></div><div class="two-fields"><div class="field"><label>Time</label><input name="time"></div><div class="field"><label>Stall no.</label><input name="stall"></div></div><div class="field"><label>Map link</label><input name="map"></div><div class="field"><label>Details</label><textarea name="details"></textarea></div><button class="primary">Publish event</button></form><div style="margin-top:18px">${events.map(e=>`<div class="notice-row"><strong>${esc(e.city)}</strong><span>${formatDate(e.date)}</span><span>${esc(e.title)}</span><button class="mini danger" onclick="deleteEvent(${e.id})">Delete</button></div>`).join('')}</div></div>`}
function userAdmin(){if(currentUser().role!=='Owner')return '<div class="note">Only Owner can manage users.</div>';return `<div class="admin-card"><h2>Admin & agent logins</h2><p>Owner can issue, disable and permission-control staff logins.</p><form id="userForm"><div class="two-fields"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Login ID</label><input name="username" required></div></div><div class="two-fields"><div class="field"><label>Password</label><input name="password" required></div><div class="field"><label>Role</label><select name="role"><option>Agent</option><option>Admin</option></select></div></div><label>Permissions</label><div class="permission-grid">${['products','orders','returns','events'].map(p=>`<label class="permission-chip"><input type="checkbox" name="perm" value="${p}"> ${labels[p]}</label>`).join('')}</div><button class="primary">Create login</button></form><div style="margin-top:20px">${users.map(u=>`<div class="user-row"><div><strong>${esc(u.name)}</strong><br><small>${esc(u.username)}</small></div><span class="role-badge">${esc(u.role)}</span><span>${u.active?'Active':'Disabled'}<br><small>${esc((u.permissions||[]).join(', '))}</small></span>${u.role==='Owner'?'<span>Protected</span>':`<button class="mini" onclick="toggleUser(${u.id})">${u.active?'Disable':'Enable'}</button>`}</div>`).join('')}</div></div>`}
function settingsAdmin(){return `<form class="admin-card" id="settingsForm"><h2>Payment & store settings</h2><div class="field"><label>Bank name</label><input name="bankName" value="${esc(settings.bankName)}"></div><div class="field"><label>Account title</label><input name="accountTitle" value="${esc(settings.accountTitle)}"></div><div class="field"><label>Account number</label><input name="accountNumber" value="${esc(settings.accountNumber)}"></div><div class="field"><label>IBAN</label><input name="iban" value="${esc(settings.iban)}"></div><div class="field"><label>Payment QR image</label><input id="qrFile" type="file" accept="image/*"></div>${settings.qrImage?`<div class="qr-box"><img src="${settings.qrImage}"></div>`:''}<div class="permission-grid"><label class="permission-chip"><input type="checkbox" name="bankEnabled" ${settings.bankEnabled?'checked':''}> Bank transfer</label><label class="permission-chip"><input type="checkbox" name="qrEnabled" ${settings.qrEnabled?'checked':''}> QR payment</label><label class="permission-chip"><input type="checkbox" name="cardEnabled" ${settings.cardEnabled?'checked':''}> Card gateway</label></div><div class="field"><label>Reservation period (hours)</label><input type="number" name="reserveHours" value="${settings.reserveHours||24}"></div><div class="field"><label>Refund policy text</label><textarea name="returnDaysText">${esc(settings.returnDaysText)}</textarea></div><button class="primary">Save settings</button></form>`}
function wireAdmin(tab){if(tab==='creations'){const f=document.getElementById('creationForm');if(f)f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)),file=document.getElementById('creationPic').files[0];if(creations.some(c=>c.id.toLowerCase()===d.code.trim().toLowerCase())){alert('Design code already exists.');return}if(!file){alert('Please add a picture.');return}if(file.size>900000){alert('Use image under 900 KB in this local prototype. Production storage will support larger images.');return}if(!confirm('Save / Proceed with this gallery design?'))return;const img=await readFile(file);creations.unshift({id:d.code.trim().toUpperCase(),title:d.title,cat:d.cat,status:d.status,season:d.season,img,custom:true,note:d.note});log(`Creation added: ${d.code}`);save();admin('creations')}};if(tab==='orders')document.querySelectorAll('.order-edit-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();saveOrderEdit(f)});if(tab==='returns')document.querySelectorAll('.return-edit-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();saveReturnEdit(f)});if(tab==='events')document.getElementById('eventForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!confirm('Publish this stall / event?'))return;events.unshift({id:Date.now(),city:d.city,venue:d.venue,title:d.title,date:d.date,time:d.time,stall:d.stall,map:d.map,status:'Upcoming',img:A.collection,details:d.details});log(`Event added: ${d.title}`);save();admin('events')};if(tab==='users'&&document.getElementById('userForm'))document.getElementById('userForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),username=d.get('username').trim();if(users.some(u=>u.username===username)){alert('Login ID already exists.');return}if(!confirm('Create this login with the selected permissions?'))return;users.push({id:Date.now(),name:d.get('name'),username,password:d.get('password'),role:d.get('role'),active:true,permissions:d.getAll('perm')});log(`User created: ${username}`);save();admin('users')};if(tab==='settings'){const form=document.getElementById('settingsForm'),file=document.getElementById('qrFile');let qr=settings.qrImage;file.onchange=async()=>{const f=file.files[0];if(f&&f.size<700000)qr=await readFile(f);else if(f)alert('Use QR image under 700 KB for prototype.')};form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));if(!confirm('Save these payment and store settings?'))return;settings={...settings,...d,bankEnabled:form.bankEnabled.checked,qrEnabled:form.qrEnabled.checked,cardEnabled:form.cardEnabled.checked,reserveHours:Number(d.reserveHours)||24,qrImage:qr};log('Payment/store settings updated');save();admin('settings')}}}
function toggleUser(id){const u=users.find(x=>x.id===id);if(u&&u.role!=='Owner'){if(!confirm(`${u.active?'Disable':'Enable'} login ${u.username}?`))return;u.active=!u.active;log(`${u.username} ${u.active?'enabled':'disabled'}`);save();admin('users')}}
function deleteEvent(id){if(confirm('Delete this event?')){events=events.filter(e=>e.id!==id);log(`Event ${id} deleted`);save();admin('events')}}
function readFile(file){return new Promise(res=>{const r=new FileReader();r.onload=()=>res(r.result);r.readAsDataURL(file)})}
function route(){const raw=location.hash||'#home';if(raw.startsWith('#product/'))productPage(raw.split('/')[1]);else if(raw.startsWith('#shop')){const m=raw.match(/cat=([^&]+)/);shop(m?decodeURIComponent(m[1]):'All')}else if(raw.startsWith('#custom'))custom();else if(raw.startsWith('#creations')){const m=raw.match(/cat=([^&]+)/);creationsPage(m?decodeURIComponent(m[1]):'All');}else if(raw==='#stalls')stalls();else if(raw==='#story')story();else if(raw==='#track')track();else if(raw==='#returns')returnsPolicy();else if(raw.startsWith('#return-request'))returnRequest();else if(raw==='#checkout')checkout();else home();document.getElementById('nav').classList.remove('open');window.scrollTo(0,0)}
document.addEventListener('keydown',e=>{if(!document.getElementById('lightbox')?.classList.contains('open'))return;if(e.key==='Escape')closeLightbox();if(e.key==='ArrowRight')moveLightbox(1);if(e.key==='ArrowLeft')moveLightbox(-1)});
window.addEventListener('hashchange',route);document.getElementById('cartBtn').onclick=()=>{renderCart();openCart()};document.getElementById('closeCart').onclick=closeCart;document.getElementById('drawerBackdrop').onclick=closeCart;document.getElementById('checkoutBtn').onclick=()=>location.hash='#checkout';document.getElementById('menuBtn').onclick=()=>document.getElementById('nav').classList.toggle('open');updateCartCount();renderCart();route();

// Cloudflare V4.2 UAT sync layer. D1 is preferred; local browser data remains fallback during migration.
async function v42Sync(){
  try{
    const [pr,cr,er]=await Promise.all([fetch('/api/products'),fetch('/api/creations'),fetch('/api/events')]);
    if(pr.ok){const j=await pr.json();if(j.ok&&j.products?.length){products=j.products.map((p,i)=>({id:p.id,code:p.code,name:p.name,cat:p.category,price:Number(p.price_pkr)||0,discount:p.discount_type==='percent'?Number(p.discount_value)||0:0,state:({available:'Available',reserved:'Reserved',sold_locked:'Sold & Locked',seasonal:'Seasonal',coming_soon:'Coming Soon',archive:'Archived'})[p.status]||p.status,img:p.image_url||A.collection,images:[p.image_url||A.collection],desc:p.description||'',featured:!!p.featured,rating:4.9,reviewCount:0,reviews:[]}));save();}}
    if(cr.ok){const j=await cr.json();if(j.ok&&j.creations?.length){creations=j.creations.map(c=>({id:c.code,title:c.title,cat:c.category,status:c.status,season:c.season||'',img:c.image_url||A.collection,custom:!!c.custom_possible,note:c.note||''}));save();}}
    if(er.ok){const j=await er.json();if(j.ok&&j.events?.length){events=j.events.map(e=>({id:e.id,city:e.city||'',venue:e.venue||'',title:e.title,date:e.event_date||'',time:e.timing||'',stall:e.stall_no||'',map:e.maps_url||'',status:e.status||'Upcoming',img:e.asset_url||A.collection,details:e.details||'',interestedYes:Number(e.interested_yes)||0}));save();}}
    route();renderCart();
  }catch(e){console.warn('V4.2 API sync unavailable; using local UAT data.',e)}
}
setTimeout(v42Sync,50);

// V4.4.2 — unified D1 tracking + guided customer assistant
function showUpcomingEventNotice(){if(sessionStorage.getItem('ssEventNoticeDismissed'))return;const today=new Date().toISOString().slice(0,10),next=[...events].filter(e=>e.date>=today&&String(e.status).toLowerCase()!=='completed').sort((a,b)=>a.date.localeCompare(b.date))[0];if(!next)return;let el=document.getElementById('eventNotice');if(el)el.remove();el=document.createElement('aside');el.id='eventNotice';el.className='event-notice';el.innerHTML=`<button class="event-notice-x" aria-label="Dismiss">×</button><div class="eyebrow">Upcoming Event</div><strong>${esc(next.title)}</strong><span>${esc(next.city)} • ${formatDate(next.date)}</span><small>Event discounts available • extra discount for customers who select “Yes”.</small><button class="event-notice-open">View event</button>`;document.body.appendChild(el);el.querySelector('.event-notice-x').onclick=e=>{e.stopPropagation();sessionStorage.setItem('ssEventNoticeDismissed','1');el.remove()};el.querySelector('.event-notice-open').onclick=()=>location.hash='#stalls'}
function mountAIAssistant(){if(document.getElementById('ssAiBtn'))return;const btn=document.createElement('button');btn.id='ssAiBtn';btn.className='ai-fab';btn.textContent='Ask SS ✨';const box=document.createElement('section');box.id='ssAiBox';box.className='ai-box';box.innerHTML=`<div class="ai-head"><div><strong>SS Collections Assistant</strong><small>Products • Orders • Events • Custom work</small></div><button id="ssAiClose">×</button></div><div id="ssAiMessages" class="ai-messages"><div class="ai-msg bot">Assalam-o-Alaikum! How may I help you today? You can write in English, Urdu or Roman Urdu.</div></div><form id="ssAiForm" class="ai-form"><input name="message" placeholder="Ask about a product, order or event…" maxlength="1200" required><button>Send</button></form>`;document.body.append(btn,box);btn.onclick=()=>box.classList.toggle('open');box.querySelector('#ssAiClose').onclick=()=>box.classList.remove('open');box.querySelector('#ssAiForm').onsubmit=async e=>{e.preventDefault();const input=e.target.message,msg=input.value.trim();if(!msg)return;const area=box.querySelector('#ssAiMessages');area.insertAdjacentHTML('beforeend',`<div class="ai-msg user">${esc(msg)}</div>`);input.value='';const wait=document.createElement('div');wait.className='ai-msg bot';wait.textContent='Thinking…';area.appendChild(wait);area.scrollTop=area.scrollHeight;try{const r=await fetch('/api/ai/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:msg,page:location.hash||'#home'})}),j=await r.json();wait.textContent=j.answer||j.error||'Please contact SS Collections on WhatsApp.'}catch(err){wait.textContent='I am temporarily unavailable. Please contact SS Collections on WhatsApp.'}area.scrollTop=area.scrollHeight}}
setTimeout(()=>{showUpcomingEventNotice();mountAIAssistant()},900);


// ===== V4.4.2 functional overrides =====
async function showTrack(q){const r=document.getElementById('trackResult');r.innerHTML='<div class="note" style="margin-top:20px">Checking live order information…</div>';try{const resp=await fetch('/api/orders/'+encodeURIComponent(q)),j=await resp.json();if(!resp.ok||!j.ok)throw new Error(j.error||'Order not found');const o=j.order,items=o.items||[];const status=String(o.order_status||'').replaceAll('_',' '),payment=String(o.payment_status||'').replaceAll('_',' ');r.innerHTML=`<div class="success-box"><strong>${esc(o.order_no)}</strong><br>${esc(o.customer_name||'')} • ${fmt(o.amount_pkr||0)}<br><span class="small-muted">Payment: ${esc(payment)} • Status: ${esc(status)}</span></div><div class="track-live-items"><h3>Products</h3>${items.map(i=>`<div class="summary-line"><span><strong>${esc(i.product_snapshot_code||'')}</strong> — ${esc(i.product_snapshot_name||'')}</span><strong>${fmt(i.unit_price_pkr||0)}</strong></div>`).join('')}</div>${o.dispatch_working_days?`<div class="bank-box"><strong>Expected dispatch</strong><br>${Number(o.dispatch_working_days)} working day${Number(o.dispatch_working_days)===1?'':'s'} from payment confirmation.</div>`:''}${o.tracking_id?`<div class="bank-box"><strong>Courier / tracking</strong><br>${esc(o.courier_name||'Courier')}: <strong>${esc(o.tracking_id)}</strong></div>`:''}${o.order_status==='dispatched'?'<div class="success-box">✓ Your order has been dispatched.</div>':''}${o.order_status==='delivered'?`<div class="button-row"><a class="secondary" href="#return-request?order=${encodeURIComponent(o.order_no)}">Report wrong / damaged product</a></div>`:''}`;}catch(err){r.innerHTML=`<div class="note" style="margin-top:20px">${esc(err.message||'Order not found. Please check the order number.')}</div>`}}

async function custom(){const m=(location.hash||'').match(/ref=(\d+)/),cm=(location.hash||'').match(/code=([^&]+)/);let p=m?products.find(x=>x.id==m[1]):null,c=cm?creations.find(x=>x.id===decodeURIComponent(cm[1])):null;if(cm){try{const rr=await fetch('/api/creations/'+encodeURIComponent(decodeURIComponent(cm[1]))),jj=await rr.json();if(rr.ok&&jj.ok){const x=jj.creation;c={id:x.code,title:x.title,cat:x.category,status:x.status,season:x.season||'',img:x.image_url||A.collection,custom:!!x.custom_possible,note:x.note||''}}}catch(e){}}app.innerHTML=`<section class="custom-page"><h1>Custom order</h1><div class="custom-grid"><div class="custom-preview">${p||c?mediaFrame((p||c).img,(p||c).name||(p||c).title):''}${c?`<div class="design-code">Reference: ${esc(c.id)}</div>`:''}</div><form class="form-card" id="customForm"><h2>${p?'Inspired by: '+esc(p.name):c?'Reference design: '+esc(c.id)+' • '+esc(c.title):'Tell us what you want'}</h2>${p||c?'<div class="unique-note">The reference design will not be copied identically. A new unique piece can be inspired by its style, colour, craft or technique.</div>':''}<div class="field"><label>Name</label><input name="customer_name" required></div><div class="field"><label>WhatsApp number</label><input name="whatsapp" required></div><div class="field"><label>Product type</label><select name="product_type"><option>Bag</option><option>Travel / office bag</option><option>Dress / clothing</option><option>Jewellery</option><option>Hair accessory</option><option>Shoes</option><option>Home décor</option><option>Other</option></select></div><div class="field"><label>Colour / size / measurements</label><input name="colour_size"></div><div class="field"><label>Your own reference image (optional)</label><input name="media" type="file" accept="image/*"></div><div class="field"><label>Instructions</label><textarea name="instructions"></textarea></div><button class="primary full">Submit custom request</button></form></div></section>`;document.getElementById('customForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);fd.set('reference_code',c?.id||p?.code||'');try{const rr=await fetch('/api/custom-requests',{method:'POST',body:fd}),jj=await rr.json();if(!rr.ok)throw new Error(jj.error||'Could not submit');alert('Thank you. Your custom request has been received by SS Collections.');location.hash='#home'}catch(err){alert(err.message)}}}

function showUpcomingEventNotice(){if(sessionStorage.getItem('ssEventNoticeDismissed'))return;const today=new Date().toISOString().slice(0,10),next=[...events].filter(e=>e.date>=today&&String(e.status).toLowerCase()!=='completed').sort((a,b)=>a.date.localeCompare(b.date))[0];if(!next)return;document.getElementById('eventNotice')?.remove();const el=document.createElement('aside');el.id='eventNotice';el.className='event-notice event-notice-v442';el.innerHTML=`<button class="event-notice-x" aria-label="Dismiss">×</button><div class="eyebrow">Upcoming Event</div><div class="event-city">${esc(next.city||'Upcoming')}</div><div class="event-venue">${esc(next.venue||next.title||'')}</div><span>${formatDate(next.date)}</span><small>Event discounts available • extra discount for customers who select “Yes”.</small><button class="event-notice-open">View event</button>`;document.body.appendChild(el);el.querySelector('.event-notice-x').onclick=e=>{e.stopPropagation();sessionStorage.setItem('ssEventNoticeDismissed','1');el.remove()};el.querySelector('.event-notice-open').onclick=()=>location.hash='#stalls'}

function aiMenuHTML(){return `<div class="ai-quick"><button data-ai="Shop Products">🛍 Shop Products</button><button data-ai="My Order">📦 My Order</button><button data-ai="Request Similar">🎨 Request Similar</button><button data-ai="Upcoming Events">📍 Events</button><button data-ai="Payment Information">💳 Payment</button><button data-ai="Delivery & Tracking">🚚 Delivery & Tracking</button><button data-ai="Returns">↩ Returns</button><button data-ai="Other Help">💬 Other Help</button></div>`}
function aiProductCard(x){const img=x.image_url||A.collection,price=x.price_pkr!=null?fmt(Math.round(Number(x.price_pkr)*(1-(Number(x.discount_value)||0)/100))):'',isCreation=x.kind==='creation';return `<div class="ai-product"><img src="${img}" alt=""><div><strong>${esc(x.code||'')}</strong><br>${esc(x.name||'')}<br><small>${esc(String(x.status||'').replaceAll('_',' '))}</small>${price?`<div>${price}</div>`:''}<div class="ai-card-actions">${!isCreation&&x.id?`<a href="#product/${x.id}">View</a>${x.status==='available'?`<button onclick="addToCart(${x.id})">Buy</button>`:''}`:`<a href="#custom?code=${encodeURIComponent(x.code)}">Request Similar</a>`}</div></div></div>`}
function renderAiResponse(area,j){let html=`<div class="ai-msg bot"><div>${esc(j.answer||'')}</div>`;if(j.mode==='menu')html+=aiMenuHTML();if(j.available?.length){html+='<h4>Available to Buy</h4>'+j.available.map(aiProductCard).join('')}if(j.creations?.length){html+='<h4>Our Creations — Request Similar</h4>'+j.creations.map(aiProductCard).join('')}if(j.products?.length)html+=j.products.map(aiProductCard).join('');if(j.orders?.length){html+=j.orders.map(o=>`<div class="ai-order"><strong>${esc(o.order_no)}</strong><br>Payment: ${esc(String(o.payment_status||'').replaceAll('_',' '))}<br>Status: ${esc(String(o.order_status||'').replaceAll('_',' '))}${o.dispatch_working_days?`<br>Dispatch: ${o.dispatch_working_days} working days`:''}${o.tracking_id?`<br>Tracking: <strong>${esc(o.courier_name||'')} ${esc(o.tracking_id)}</strong>`:''}<div>${(o.items||[]).map(i=>`<small>${esc(i.code||'')} — ${esc(i.name||'')}</small>`).join('<br>')}</div></div>`).join('')}if(j.events?.length)html+=j.events.map(e=>`<div class="ai-order"><strong>${esc(e.city||'')}</strong><br>${esc(e.title||'')}<br><small>${esc(e.venue||'')} • ${esc(e.event_date||'')}</small><br><a href="#stalls">View event</a></div>`).join('');if(j.options?.length&&j.mode!=='menu')html+=`<div class="ai-quick">${j.options.map(x=>`<button data-ai="${esc(x)}">${esc(x)}</button>`).join('')}</div>`;html+='</div>';area.insertAdjacentHTML('beforeend',html);area.querySelectorAll('[data-ai]').forEach(b=>{if(!b.dataset.wired){b.dataset.wired='1';b.onclick=()=>sendAiMessage(b.dataset.ai)}});area.scrollTop=area.scrollHeight}
let aiArea=null,aiInput=null;async function sendAiMessage(msg){if(!aiArea)return;aiArea.insertAdjacentHTML('beforeend',`<div class="ai-msg user">${esc(msg)}</div>`);const wait=document.createElement('div');wait.className='ai-msg bot';wait.textContent='Checking…';aiArea.appendChild(wait);aiArea.scrollTop=aiArea.scrollHeight;try{const rr=await fetch('/api/ai/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:msg,page:location.hash||'#home'})}),j=await rr.json();wait.remove();renderAiResponse(aiArea,j)}catch(e){wait.textContent='Please try again or contact SS Collections on WhatsApp.'}}
function mountAIAssistant(){if(document.getElementById('ssAiBtn'))return;const btn=document.createElement('button');btn.id='ssAiBtn';btn.className='ai-fab';btn.textContent='Ask SS ✨';const box=document.createElement('section');box.id='ssAiBox';box.className='ai-box ai-box-v442';box.innerHTML=`<div class="ai-head"><div><strong>ASK SS</strong><small>Click, enter an Order No., Product Code, or a simple word like “bag”.</small></div><button id="ssAiClose">×</button></div><div id="ssAiMessages" class="ai-messages"><div class="ai-msg bot">How can I help you?${aiMenuHTML()}</div></div><form id="ssAiForm" class="ai-form"><input name="message" placeholder="Order no., product code, bag, dress…" maxlength="1200" required><button>Send</button></form>`;document.body.append(btn,box);aiArea=box.querySelector('#ssAiMessages');aiInput=box.querySelector('input[name=message]');btn.onclick=()=>box.classList.toggle('open');box.querySelector('#ssAiClose').onclick=()=>box.classList.remove('open');box.querySelectorAll('[data-ai]').forEach(b=>b.onclick=()=>sendAiMessage(b.dataset.ai));box.querySelector('#ssAiForm').onsubmit=e=>{e.preventDefault();const msg=aiInput.value.trim();if(!msg)return;aiInput.value='';sendAiMessage(msg)}}
// Re-mount V4.4.2 UI after earlier mount if needed
setTimeout(()=>{document.getElementById('eventNotice')?.remove();showUpcomingEventNotice();document.getElementById('ssAiBtn')?.remove();document.getElementById('ssAiBox')?.remove();mountAIAssistant()},1100);
